using System.Collections.Generic;using System.Text;public class Solution{List<string>o=new();void F(char[]h,bool[]u,StringBuilder c,char?mid){if(c.Length==h.Length){string a=c.ToString();var r=new StringBuilder(a);if(mid.HasValue)r.Append(mid.Value);for(int i=a.Length-1;i>=0;i--)r.Append(a[i]);o.Add(r.ToString());return;}for(int i=0;i<h.Length;i++){if(u[i]||(i>0&&h[i]==h[i-1]&&!u[i-1]))continue;u[i]=true;c.Append(h[i]);F(h,u,c,mid);c.Length--;u[i]=false;}}public IList<string> GeneratePalindromes(string s){int[]c=new int[256];foreach(char x in s)c[x]++;int odd=0;char?mid=null;var h=new StringBuilder();for(int i=0;i<256;i++){if((c[i]&1)==1){odd++;mid=(char)i;}for(int j=0;j<c[i]/2;j++)h.Append((char)i);}if(odd>1)return o;F(h.ToString().ToCharArray(),new bool[h.Length],new StringBuilder(),mid);return o;}}
